SELECT p.gender, p.anchor_year, s.admission_type_id, AVG(s.length_of_stay) AS average_length_of_stay FROM patients p JOIN admissions s ON p.subject_id = s.subject_id WHERE p.gender = 'F' AND p.anchor_year BETWEEN 59 AND 69 AND s.admission_type_id = 10001 AND s.discharge_status_id = 10001 GROUP BY p.gender, p.anchor_year, s.admission_type_id ORDER BY average_length_of_stay NULLS LAST;